<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN','RESPONSABLE']);$db=Database::connection();$id=max(0,(int)($_GET['id']??$_POST['id']??0));$data=['code'=>'','raison_sociale'=>'','email'=>'','telephone'=>'','adresse'=>'','contact_commercial'=>'','date_partenariat'=>'','statut'=>'active'];$errors=[];
if($id){$s=$db->prepare('SELECT * FROM compagnies WHERE id=?');$s->execute([$id]);$data=$s->fetch()?:exit('Compagnie introuvable.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach(array_keys($data) as $f)if(isset($_POST[$f]))$data[$f]=trim((string)$_POST[$f]);if($data['code']===''||$data['raison_sociale']==='')$errors[]='Le code et la raison sociale sont obligatoires.';if($data['email']!==''&&!filter_var($data['email'],FILTER_VALIDATE_EMAIL))$errors[]='E-mail invalide.';if(!$errors){$v=['code'=>strtoupper($data['code']),'nom'=>$data['raison_sociale'],'email'=>$data['email']?:null,'tel'=>$data['telephone']?:null,'adresse'=>$data['adresse']?:null,'contact'=>$data['contact_commercial']?:null,'date'=>$data['date_partenariat']?:null,'statut'=>$data['statut']];if($id){$v['id']=$id;$sql='UPDATE compagnies SET code=:code,raison_sociale=:nom,email=:email,telephone=:tel,adresse=:adresse,contact_commercial=:contact,date_partenariat=:date,statut=:statut WHERE id=:id';}else{$sql='INSERT INTO compagnies(code,raison_sociale,email,telephone,adresse,contact_commercial,date_partenariat,statut) VALUES(:code,:nom,:email,:tel,:adresse,:contact,:date,:statut)';}try{$db->prepare($sql)->execute($v);$sid=$id?:((int)$db->lastInsertId());audit($id?'MODIFICATION':'CREATION','compagnie',$sid);flash('success',$id?'Compagnie modifiée.':'Compagnie créée.');redirect('compagnies/index.php');}catch(PDOException $e){$errors[]='Ce code existe déjà.';}}}
$title=$id?'Modifier la compagnie':'Nouvelle compagnie';require __DIR__.'/../../includes/header.php';?>
<div class="form-shell"><div class="page-heading"><h1 class="h3"><?= e($title) ?></h1><a class="btn btn-outline-secondary" href="index.php">Retour</a></div><?php if($errors): ?><div class="alert alert-danger"><?= e(implode(' ',$errors)) ?></div><?php endif; ?><form method="post" class="card card-body needs-validation" novalidate><?= csrf_field() ?><input type="hidden" name="id" value="<?= $id ?>"><div class="row g-3"><div class="col-md-4"><label class="form-label">Code *</label><input class="form-control" name="code" value="<?= e($data['code']) ?>" required></div><div class="col-md-8"><label class="form-label">Raison sociale *</label><input class="form-control" name="raison_sociale" value="<?= e($data['raison_sociale']) ?>" required></div><div class="col-md-6"><label class="form-label">E-mail</label><input type="email" class="form-control" name="email" value="<?= e($data['email']) ?>"></div><div class="col-md-6"><label class="form-label">Téléphone</label><input class="form-control" name="telephone" value="<?= e($data['telephone']) ?>"></div><div class="col-md-6"><label class="form-label">Contact commercial</label><input class="form-control" name="contact_commercial" value="<?= e($data['contact_commercial']) ?>"></div><div class="col-md-3"><label class="form-label">Partenariat</label><input type="date" class="form-control" name="date_partenariat" value="<?= e($data['date_partenariat']) ?>"></div><div class="col-md-3"><label class="form-label">Statut</label><select class="form-select" name="statut"><option value="active" <?= $data['statut']==='active'?'selected':'' ?>>Active</option><option value="inactive" <?= $data['statut']==='inactive'?'selected':'' ?>>Inactive</option></select></div><div class="col-12"><label class="form-label">Adresse</label><input class="form-control" name="adresse" value="<?= e($data['adresse']) ?>"></div></div><div class="text-end mt-4"><button class="btn btn-primary">Enregistrer</button></div></form></div><?php require __DIR__.'/../../includes/footer.php'; ?>
